import{_ as e,o as i,f as t,a6 as r}from"./chunks/framework.BFhbG0o2.js";const m=JSON.parse('{"title":"AI 冲击下，设计师网站应该展示什么","description":"从作品陈列转向案例证据、工作流与可复用知识。","frontmatter":{"title":"AI 冲击下，设计师网站应该展示什么","description":"从作品陈列转向案例证据、工作流与可复用知识。","pageClass":"page-article-detail","status":"published"},"headers":[],"relativePath":"blog/ai-designer-positioning.md","filePath":"blog/ai-designer-positioning.md"}'),o={name:"blog/ai-designer-positioning.md"};function l(n,a,s,h,d,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-冲击下-设计师网站应该展示什么" tabindex="-1">AI 冲击下，设计师网站应该展示什么 <a class="header-anchor" href="#ai-冲击下-设计师网站应该展示什么" aria-label="Permalink to &quot;AI 冲击下，设计师网站应该展示什么&quot;">​</a></h1><p>生成工具让“做出一张看起来不错的图”越来越容易。设计师网站如果仍然只堆最终画面，访客很难判断：你解决了什么问题、做出了哪些判断，以及这些能力能否在下一个项目中重复出现。</p><h2 id="作品图不等于案例证据" tabindex="-1">作品图不等于案例证据 <a class="header-anchor" href="#作品图不等于案例证据" aria-label="Permalink to &quot;作品图不等于案例证据&quot;">​</a></h2><p>一个可信案例至少需要说明目标、限制、个人角色、关键判断、过程和结果。最终画面仍然重要，但它只是证据链的一部分。</p><p>当项目涉及 AI，还应该说明哪些部分由模型辅助、哪些部分由人工控制，以及如何处理真实性、版权和品牌一致性。</p><h2 id="工作流解释能力如何重复" tabindex="-1">工作流解释能力如何重复 <a class="header-anchor" href="#工作流解释能力如何重复" aria-label="Permalink to &quot;工作流解释能力如何重复&quot;">​</a></h2><p>案例回答“这次做成了什么”，工作流回答“下一次为什么仍然能做成”。需求如何被拆解、变量如何被控制、结果如何被筛选、交付如何被复盘，这些才是长期能力。</p><h2 id="知识库让专业影响力持续积累" tabindex="-1">知识库让专业影响力持续积累 <a class="header-anchor" href="#知识库让专业影响力持续积累" aria-label="Permalink to &quot;知识库让专业影响力持续积累&quot;">​</a></h2><p>不是所有经验都需要写成长文章。一个经过验证的 Prompt 结构、一份检查清单或一次项目复盘，都可以成为有价值的知识资产。关键在于它们必须回到真实实践，而不是为了更新频率存在。</p><h2 id="个人介绍应该放在哪里" tabindex="-1">个人介绍应该放在哪里 <a class="header-anchor" href="#个人介绍应该放在哪里" aria-label="Permalink to &quot;个人介绍应该放在哪里&quot;">​</a></h2><p>个人背景负责解释这些方法从何而来，但不应该压过实践本身。先让访客看到你如何解决问题，再用经历、成果和合作方式补充可信度，网站就不再像一份在线简历。</p><h2 id="关联内容" tabindex="-1">关联内容 <a class="header-anchor" href="#关联内容" aria-label="Permalink to &quot;关联内容&quot;">​</a></h2><ul><li><a href="/aigc/commercial-visual-system.html">AI 商业视觉生产系统</a></li><li><a href="/portfolio/ecommerce-visual.html">专业医疗产品电商视觉系统</a></li><li><a href="/knowledge/">知识库</a></li></ul><p><a href="/blog/">← 返回方法与洞察</a></p>',14)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
